import 'package:flutter/material.dart';
import 'dashboard_service.dart';
import 'parent_transport_card.dart';
class LiveDashboard extends StatefulWidget{final String role;const LiveDashboard({super.key,required this.role});@override State<LiveDashboard>createState()=>_LiveDashboardState();}
class _LiveDashboardState extends State<LiveDashboard>{final service=DashboardService();Map<String,dynamic>? data;String? error;bool loading=true;@override void initState(){super.initState();_load();}Future<void>_load()async{setState(()=>loading=true);try{final d=widget.role=='parent'?await service.parentOverview():widget.role=='parent_notifications'?await service.notifications():await service.students();if(mounted)setState((){data=d;error=null;loading=false;});}catch(e){if(mounted)setState((){error=e.toString();loading=false;});}}@override Widget build(BuildContext c){if(loading)return const Center(child:CircularProgressIndicator());if(error!=null)return Center(child:Column(mainAxisSize:MainAxisSize.min,children:[Text(error!),const SizedBox(height:12),FilledButton(onPressed:_load,child:const Text('Retry'))]));final children=(data?['students']??data?['children'] as List?)??const [];return RefreshIndicator(onRefresh:_load,child:ListView(padding:const EdgeInsets.all(16),children:[Text('My Children',style:Theme.of(c).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.w800)),const SizedBox(height:12),...children.asMap().entries.map((e){final x=Map<String,dynamic>.from(e.value as Map);final id=x['id']?.toString();final fees=Map<String,dynamic>.from((x['fees']as Map?)??{});final a=Map<String,dynamic>.from((x['attendance']as Map?)??{});return TweenAnimationBuilder<double>(tween:Tween(begin:0,end:1),duration:Duration(milliseconds:350+e.key*90),builder:(_,v,child)=>Transform.translate(offset:Offset(0,16*(1-v)),child:Opacity(opacity:v,child:child)),child:Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('${x['fullName']??x['name']??'Student'}',style:const TextStyle(fontSize:18,fontWeight:FontWeight.w800)),const SizedBox(height:10),Row(mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[Text('Fees ₹${fees['outstanding']??x['outstanding']??0}'),Text('Attendance ${a['attendancePercent']??0}%')]),if(id!=null&&widget.role=='parent')ParentTransportCard(studentId:id)]))));}),if(children.isEmpty)const Card(child:Padding(padding:EdgeInsets.all(20),child:Text('No linked children found.'))]));}}
